// Tests for Lab 01b - Tip Calculator.
//
// Replaces the default counter test generated by `flutter create`.
//   * Unit tests check the pure functions computeTip and parseBill.
//   * Widget tests drive the real screen: typing a bill, changing the
//     percentage, entering invalid input, and splitting the bill.
//
// Run with: flutter test

import 'package:flutter_test/flutter_test.dart';
import 'package:material_ui/material_ui.dart';

import 'package:tip_calculator/main.dart';

void main() {
  group('computeTip', () {
    test('500 at 15% gives a 75.00 tip and a 575.00 total', () {
      final result = computeTip(500, 15);
      expect(result.tip, 75.0);
      expect(result.total, 575.0);
    });

    test('works for 10% and 20%', () {
      expect(computeTip(200, 10).tip, 20.0);
      expect(computeTip(200, 10).total, 220.0);
      expect(computeTip(200, 20).tip, 40.0);
      expect(computeTip(200, 20).total, 240.0);
    });

    test('a zero bill gives a zero tip and total', () {
      final result = computeTip(0, 15);
      expect(result.tip, 0.0);
      expect(result.total, 0.0);
    });

    test('money is shown with exactly two decimals', () {
      final result = computeTip(123.45, 15);
      expect(result.tip.toStringAsFixed(2), '18.52');
      expect(result.total.toStringAsFixed(2), '141.97');
    });
  });

  group('parseBill', () {
    test('parses numbers and ignores surrounding spaces', () {
      expect(parseBill('500'), 500.0);
      expect(parseBill('  12.50 '), 12.5);
    });

    test('returns null for empty or invalid input', () {
      expect(parseBill(''), isNull);
      expect(parseBill('   '), isNull);
      expect(parseBill('abc'), isNull);
    });
  });

  group('TipPage', () {
    testWidgets('starts with 15% selected and asks for an amount', (
      tester,
    ) async {
      await tester.pumpWidget(const TipApp());

      expect(find.text('Tip Calculator'), findsOneWidget);
      expect(find.text('Enter a valid amount'), findsOneWidget);

      final button = tester.widget<SegmentedButton<int>>(
        find.byType(SegmentedButton<int>),
      );
      expect(button.selected, {15});
    });

    testWidgets('bill 500 at 15% shows tip 75.00 and total 575.00', (
      tester,
    ) async {
      await tester.pumpWidget(const TipApp());

      await tester.enterText(find.byKey(const Key('billField')), '500');
      await tester.pump();

      expect(find.text('75.00'), findsOneWidget);
      expect(find.text('575.00'), findsOneWidget);
      expect(find.text('Enter a valid amount'), findsNothing);
    });

    testWidgets('changing the percentage updates the totals right away', (
      tester,
    ) async {
      await tester.pumpWidget(const TipApp());

      await tester.enterText(find.byKey(const Key('billField')), '500');
      await tester.pump();
      await tester.tap(find.text('20%'));
      await tester.pumpAndSettle();

      expect(find.text('100.00'), findsOneWidget);
      expect(find.text('600.00'), findsOneWidget);
    });

    testWidgets('invalid input shows a message instead of crashing', (
      tester,
    ) async {
      await tester.pumpWidget(const TipApp());

      for (final input in ['abc', '-5', 'NaN', '']) {
        await tester.enterText(find.byKey(const Key('billField')), input);
        await tester.pump();
        expect(find.text('Enter a valid amount'), findsOneWidget);
      }
    });

    testWidgets('splitting the bill shows the amount per person', (
      tester,
    ) async {
      await tester.pumpWidget(const TipApp());

      await tester.enterText(find.byKey(const Key('billField')), '500');
      await tester.pump();
      await tester.tap(find.byKey(const Key('incrementPeople')));
      await tester.pump();

      expect(find.text('2 people'), findsOneWidget);
      expect(find.text('287.50'), findsOneWidget);
    });
  });
}
